oxy_webhelp_navlinks = {"abr_aws_cloud_applications-d39307e60845":{"topics":[{"title":"Introduction to <span class=\"ph\">Autonomous Business Recovery for Cloud Applications<\/span>","href":"autonomous_business_recovery\/abr_cloud_apps_overview.html","menu":{"hasChildren":false},"tocID":"tocId-d39307e60865","next":"tocId-d39307e60865"},{"title":"Plan for <span class=\"ph\">Autonomous Business Recovery for Cloud Applications<\/span>","shortdesc":"<p class=\"shortdesc\">Before deploying <span class=\"ph\">Autonomous Business Recovery for Cloud Applications<\/span> in <span class=\"ph\">RSC<\/span>, plan the user and         access management for <span class=\"ph\">RSC<\/span> users who will manage cloud applications. Planning         also involves reviewing the permissions, supported resource types, and limitations of <span class=\"ph\">Autonomous Business Recovery<\/span>.<\/p>","href":"autonomous_business_recovery\/abr_plan_protection.html","attributes":{"data-id":"abr_plan_protection"},"menu":{"hasChildren":false},"tocID":"abr_plan_protection-d39307e60969","next":"abr_plan_protection-d39307e60969"},{"title":"Add AWS cloud application to <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\">Add your AWS cloud account to <span class=\"ph\">RSC<\/span>, configure a recovery account, and         create a cloud application by specifying tags or by manually selecting your AWS         resources.<\/p>","href":"autonomous_business_recovery\/abr_add_cloud_app.html","attributes":{"data-id":"abr_add_cloud_app"},"menu":{"hasChildren":false},"tocID":"abr_add_cloud_app-d39307e61091","next":"abr_add_cloud_app-d39307e61091"},{"title":"Set up protection for AWS cloud applications","shortdesc":"<p class=\"shortdesc\">Configure SLA Domains to protect the configuration resources and workloads in your         AWS cloud application using <span class=\"ph\">RSC<\/span>.<\/p>","href":"autonomous_business_recovery\/abr_set_up_protection.html","attributes":{"data-id":"abr_set_up_protection"},"menu":{"hasChildren":false},"tocID":"abr_set_up_protection-d39307e61329","next":"abr_set_up_protection-d39307e61329"},{"title":"Recover an AWS cloud application","shortdesc":"<p class=\"shortdesc\">Recover your AWS cloud application to a separate recovery AWS cloud account by using             <span class=\"ph\">RSC<\/span> to restore the workloads and configuration resources from a selected         recovery point.<\/p>","href":"autonomous_business_recovery\/abr_recover.html","attributes":{"data-id":"abr_recover"},"menu":{"hasChildren":false},"tocID":"abr_recover-d39307e61434","next":"abr_recover-d39307e61434"},{"title":"Manage AWS cloud application data","shortdesc":"<p class=\"shortdesc\">Monitor and manage your AWS cloud applications in <span class=\"ph\">RSC<\/span>, including         viewing inventory, refreshing applications, reviewing snapshots, and monitoring         events.<\/p>","href":"autonomous_business_recovery\/abr_manage_cloud_apps.html","attributes":{"data-id":"abr_manage_cloud_apps"},"menu":{"hasChildren":false},"tocID":"abr_manage_cloud_apps-d39307e61546","next":"abr_manage_cloud_apps-d39307e61546"},{"title":"Manage reports for AWS cloud applications","shortdesc":"<p class=\"shortdesc\">You can create and manage reports in <span class=\"ph\">RSC<\/span> to review protection         compliance, recovery readiness, and operational status for your AWS cloud         applications.<\/p>","href":"autonomous_business_recovery\/abr_access_reports.html","attributes":{"data-id":"abr_access_reports"},"menu":{"hasChildren":false},"tocID":"abr_access_reports-d39307e61669","next":"abr_access_reports-d39307e61669"}]}};